@push('scripts')<script>const landmarks=document.getElementById('landmarks');document.getElementById('addLandmark').addEventListener('click',()=>landmarks.insertAdjacentHTML('beforeend','<div class="landmark-row flex gap-2"><input name="landmarks[]" class="h-10 flex-1 rounded-xl border-slate-200 text-sm" placeholder="Near metro, college or hospital"><button type="button" class="remove-landmark rounded-xl bg-red-50 px-3 text-red-600"><i class="fas fa-trash"></i></button></div>'));landmarks.addEventListener('click',event=>{const button=event.target.closest('.remove-landmark');if(button&&landmarks.querySelectorAll('.landmark-row').length>1)button.closest('.landmark-row').remove();else if(button)button.closest('.landmark-row').querySelector('input').value=''});const photos=document.getElementById('roomPhotos');photos.addEventListener('change',()=>{const preview=document.getElementById('photoPreview'),label=document.getElementById('photoSelection'),files=[...photos.files];preview.innerHTML='';if(files.length>5){photos.value='';label.textContent='Select no more than 5 photos.';label.className='mt-2 text-[10px] font-bold text-red-600';return}label.className='mt-2 text-[10px] text-slate-500';label.textContent=files.length?`${files.length} photo(s) selected. The first will be the cover.`:'No photos selected.';files.forEach(file=>{const image=document.createElement('img');image.src=URL.createObjectURL(file);image.className='preview-image';preview.appendChild(image)})});const propertyTypeSelect=document.getElementById('property_type_id');const propertyCategorySelect=document.getElementById('property_category_id');function loadPropertyCategories(propertyTypeId,selectedCategoryId=null){propertyCategorySelect.innerHTML='<option value="">Select category</option>';propertyCategorySelect.disabled=true;if(!propertyTypeId)return;fetch(`{{ url('/api/v1/property-categories') }}?property_type_id=${encodeURIComponent(propertyTypeId)}`,{headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}}).then(response=>response.json()).then(payload=>{const categories=payload?.data??[];if(!Array.isArray(categories)||!categories.length){propertyCategorySelect.innerHTML='<option value="">No categories available</option>';return}categories.forEach(category=>{const option=document.createElement('option');option.value=category.id;option.textContent=category.name;propertyCategorySelect.appendChild(option)});propertyCategorySelect.disabled=false;if(selectedCategoryId){propertyCategorySelect.value=String(selectedCategoryId)}}).catch(()=>{propertyCategorySelect.innerHTML='<option value="">Unable to load categories</option>'})}propertyTypeSelect.addEventListener('change',function(){loadPropertyCategories(this.value,null)});loadPropertyCategories(propertyTypeSelect.value,'{{ old('property_category_id') }}');function toggleAdminPurposeFields(val){const isSell=val==='sell';const rentWrap=document.getElementById('admin_rent_wrap');const priceWrap=document.getElementById('admin_price_wrap');const depositWrap=document.getElementById('admin_deposit_wrap');const tenantWrap=document.getElementById('admin_tenant_wrap');const possessionWrap=document.getElementById('admin_possession_wrap');const ownershipWrap=document.getElementById('admin_ownership_wrap');if(rentWrap)rentWrap.style.display=isSell?'none':'block';if(priceWrap)priceWrap.style.display=isSell?'block':'none';if(depositWrap)depositWrap.style.display=isSell?'none':'block';if(tenantWrap)tenantWrap.style.display=isSell?'none':'block';if(possessionWrap)possessionWrap.style.display=isSell?'block':'none';if(ownershipWrap)ownershipWrap.style.display=isSell?'block':'none'}toggleAdminPurposeFields(document.getElementById('admin_purpose')?.value||'rent');</script>@endpush
